#!/usr/bin/env node
/**
 * Prints the .htaccess rules for phonemastcompany.co.uk (Apache on separate hosting), generated from
 * LEGACY_DOMAIN in src/seo/redirects.ts so the two never drift apart.
 * Run: node --disable-warning=MODULE_TYPELESS_PACKAGE_JSON scripts/generate-legacy-htaccess.mjs > legacy.htaccess
 */
import { LEGACY_DOMAIN } from "../src/seo/redirects.ts";

const SITE = "https://www.phonemastadvice.co.uk";
const esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const lines = [
  "# Generated by scripts/generate-legacy-htaccess.mjs from src/seo/redirects.ts. Do not edit by hand.",
  "# Every rule is one permanent (301) hop straight to the final https://www URL, for http and https.",
  "RewriteEngine On",
  "",
  "# Injected spam pages: gone",
  ...LEGACY_DOMAIN.gonePrefixes.map((p) => `RewriteRule ^${esc(p)} - [G,L]`),
  "",
  "# Pages with a direct equivalent",
  ...Object.entries(LEGACY_DOMAIN.map).map(([from, to]) => `RewriteRule ^${esc(from)}/?$ ${SITE}${to} [R=301,L,QSD]`),
  "",
  "# Old WordPress archives",
  ...Object.entries(LEGACY_DOMAIN.prefixMap).map(([from, to]) => `RewriteRule ^${esc(from)} ${SITE}${to} [R=301,L,QSD]`),
  "",
  "# Everything else, including the homepage",
  `RewriteRule ^ ${SITE}/ [R=301,L,QSD]`,
];
console.log(lines.join("\n"));
